<section class="settings-group"><x-section-heading tag="h3" icon="dashboard" tone="violet">Display</x-section-heading><x-setting-select name="theme" label="Appearance" :value="$values['theme']" :options="['dark'=>'Dark','light'=>'Light']" /><x-setting-select name="density" label="Table row spacing" :value="$values['density']" :options="['comfortable'=>'Comfortable','compact'=>'Compact']" /><x-setting-select name="rows" label="Rows per page" :value="$values['rows']" :options="[10=>'10 rows',20=>'20 rows',25=>'25 rows',50=>'50 rows']" /><x-setting-toggle name="reduced_motion" label="Reduce motion" :checked="$values['reduced_motion']" /><x-setting-toggle name="sound" label="Confirmation sound" :checked="$values['sound']" help="Visual feedback is always shown. Browser audio availability does not affect saved actions." /><x-button variant="secondary" data-test-sound>Test sound</x-button></section><section class="settings-group"><x-section-heading tag="h3" icon="dashboard" tone="violet">Your preferences</x-section-heading><x-setting-value label="Applies to" :value="auth()->user()->name.' · your account only'" /><x-setting-value label="Regional format" value="PHP · Philippine time (UTC+8) · 24-hour time" /></section>
